"""TL;DR + niche relevance for each recommended paper, generated by an LLM.

Two providers:
- openai:    any OpenAI-compatible chat-completions endpoint (SiliconFlow, OpenAI, Groq, Ollama...);
             same OPENAI_API_KEY / OPENAI_API_BASE secrets as zotero-arxiv-daily.
- anthropic: Claude through the official SDK (ANTHROPIC_API_KEY).
Without a provider the S2 TL;DR (when available) is used.
"""

import logging
import re

import requests

log = logging.getLogger(__name__)

SYSTEM = (
    "You help a researcher who is writing a survey on a narrow research niche. "
    "Given the niche (described by papers already in their collection) and a candidate paper, "
    "answer in {language} with exactly two lines:\n"
    "TLDR: <one or two sentences: what the paper does and its main result>\n"
    "NICHE: <one sentence: how it relates to the niche - same problem, method, baseline, or only tangential>\n"
    "Be concrete and do not invent results that are not in the abstract."
)


def build_prompt(niche_name, seed_titles, paper):
    seeds = "\n".join(f"- {t}" for t in seed_titles)
    return (f"Niche: {niche_name}\nPapers in the niche collection:\n{seeds}\n\n"
            f"Candidate paper:\nTitle: {paper.get('title', '')}\n"
            f"Abstract: {paper.get('abstract') or '(no abstract available)'}")


def parse(text):
    tldr = re.search(r"TLDR:\s*(.+)", text)
    niche = re.search(r"NICHE:\s*(.+)", text)
    if not tldr:
        return text.strip(), None
    return tldr.group(1).strip(), niche.group(1).strip() if niche else None


class Summarizer:
    def __init__(self, cfg):
        self.cfg = cfg or {}
        self.provider = (self.cfg.get("provider") or "none").lower()
        self.language = self.cfg.get("language", "Italian")
        if self.provider == "openai" and not (self.cfg.get("api_key") and self.cfg.get("model")):
            log.warning("LLM provider 'openai' needs RADAR_OPENAI_API_KEY and LLM_MODEL: "
                        "TL;DR from Semantic Scholar only")
            self.provider = "none"
        if self.provider == "anthropic":
            import anthropic
            self.client = anthropic.Anthropic()

    def summarize(self, niche_name, seed_titles, paper):
        """Returns (tldr, niche_note); falls back to the S2 TL;DR."""
        fallback = ((paper.get("tldr") or {}).get("text"), None)
        if self.provider == "none":
            return fallback
        system = SYSTEM.format(language=self.language)
        prompt = build_prompt(niche_name, seed_titles, paper)
        try:
            text = self._openai(system, prompt) if self.provider == "openai" else self._anthropic(system, prompt)
        except Exception as e:  # one failed summary must not stop the daily run
            log.warning("LLM failed for %r: %s", paper.get("title"), e)
            return fallback
        return parse(text) if text else fallback

    def _openai(self, system, prompt):
        base = self.cfg.get("base_url") or "https://api.openai.com/v1"
        r = requests.post(
            base.rstrip("/") + "/chat/completions",
            headers={"Authorization": f"Bearer {self.cfg['api_key']}"},
            json={"model": self.cfg["model"], "max_tokens": self.cfg.get("max_tokens", 1024),
                  "messages": [{"role": "system", "content": system}, {"role": "user", "content": prompt}]},
            timeout=120,
        )
        r.raise_for_status()
        return r.json()["choices"][0]["message"]["content"]

    def _anthropic(self, system, prompt):
        response = self.client.beta.messages.create(
            model=self.cfg.get("model") or "claude-opus-5-5",
            max_tokens=self.cfg.get("max_tokens", 2048),
            betas=["server-side-fallback-2026-07-01"],
            fallbacks="default",
            output_config={"effort": "low"},
            system=system,
            messages=[{"role": "user", "content": prompt}],
        )
        if response.stop_reason == "refusal":
            return None
        return "".join(b.text for b in response.content if b.type == "text")
